@@ -0,0 +1,227 @@
+export interface Task {
+  id: string;
+  duration: number;
+  dependsOn: string[];
+}
+
+export interface Plan {
+  order: string[];
+  layers: string[][];
+  earliest: Record<string, { start: number; finish: number }>;
+  totalDuration: number;
+  criticalPath: string[];
+}
+
+function comparePaths(left: string[], right: string[]): number {
+  const length = Math.min(left.length, right.length);
+  for (let index = 0; index < length; index++) {
+    const comparison = left[index]!.localeCompare(right[index]!);
+    if (comparison !== 0) return comparison;
+  }
+  return left.length - right.length;
+}
+
+export function validateInput(value: unknown): Task[] {
+  if (typeof value !== "object" || value === null || Array.isArray(value)) {
+    throw new Error("input must be a JSON object");
+  }
+
+  const input = value as Record<string, unknown>;
+  if (!Array.isArray(input.tasks)) {
+    throw new Error('"tasks" must be an array');
+  }
+
+  const tasks: Task[] = [];
+  const ids = new Set<string>();
+
+  for (let index = 0; index < input.tasks.length; index++) {
+    const raw = input.tasks[index];
+    const label = `tasks[${index}]`;
+    if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
+      throw new Error(`${label} must be an object`);
+    }
+
+    const task = raw as Record<string, unknown>;
+    if (typeof task.id !== "string" || task.id.length === 0) {
+      throw new Error(`${label}.id must be a non-empty string`);
+    }
+    if (ids.has(task.id)) {
+      throw new Error(`duplicate task id: ${task.id}`);
+    }
+    if (typeof task.duration !== "number" || !Number.isFinite(task.duration) || task.duration < 0) {
+      throw new Error(`${label}.duration must be a finite non-negative number`);
+    }
+
+    const rawDependencies = task.dependsOn ?? [];
+    if (!Array.isArray(rawDependencies)) {
+      throw new Error(`${label}.dependsOn must be an array`);
+    }
+    const dependencies: string[] = [];
+    const seenDependencies = new Set<string>();
+    for (let dependencyIndex = 0; dependencyIndex < rawDependencies.length; dependencyIndex++) {
+      const dependency = rawDependencies[dependencyIndex];
+      if (typeof dependency !== "string") {
+        throw new Error(`${label}.dependsOn[${dependencyIndex}] must be a string`);
+      }
+      if (seenDependencies.has(dependency)) {
+        throw new Error(`${label}.dependsOn contains duplicate id: ${dependency}`);
+      }
+      if (dependency === task.id) {
+        throw new Error(`${label}.dependsOn cannot contain its own id: ${task.id}`);
+      }
+      seenDependencies.add(dependency);
+      dependencies.push(dependency);
+    }
+
+    ids.add(task.id);
+    tasks.push({ id: task.id, duration: task.duration, dependsOn: dependencies });
+  }
+
+  for (const task of tasks) {
+    for (const dependency of task.dependsOn) {
+      if (!ids.has(dependency)) {
+        throw new Error(`task ${task.id} depends on unknown task: ${dependency}`);
+      }
+    }
+  }
+
+  return tasks;
+}
+
+function findCycle(tasks: Task[]): string[] | null {
+  const dependencies = new Map(tasks.map((task) => [task.id, [...task.dependsOn].sort()]));
+  const state = new Map<string, 0 | 1 | 2>();
+  const stack: string[] = [];
+
+  function visit(id: string): string[] | null {
+    state.set(id, 1);
+    stack.push(id);
+    for (const dependency of dependencies.get(id)!) {
+      if ((state.get(dependency) ?? 0) === 0) {
+        const cycle = visit(dependency);
+        if (cycle) return cycle;
+      } else if (state.get(dependency) === 1) {
+        const start = stack.indexOf(dependency);
+        return [...stack.slice(start), dependency];
+      }
+    }
+    stack.pop();
+    state.set(id, 2);
+    return null;
+  }
+
+  for (const id of [...dependencies.keys()].sort()) {
+    if ((state.get(id) ?? 0) === 0) {
+      const cycle = visit(id);
+      if (cycle) return cycle;
+    }
+  }
+  return null;
+}
+
+export function createPlan(tasks: Task[]): Plan {
+  const byId = new Map(tasks.map((task) => [task.id, task]));
+  const dependents = new Map(tasks.map((task) => [task.id, [] as string[]]));
+  const remainingDependencies = new Map<string, number>();
+  for (const task of tasks) {
+    remainingDependencies.set(task.id, task.dependsOn.length);
+    for (const dependency of task.dependsOn) {
+      dependents.get(dependency)!.push(task.id);
+    }
+  }
+  for (const ids of dependents.values()) ids.sort();
+
+  const ready = tasks.filter((task) => task.dependsOn.length === 0).map((task) => task.id).sort();
+  const order: string[] = [];
+  while (ready.length > 0) {
+    const id = ready.shift()!;
+    order.push(id);
+    for (const dependent of dependents.get(id)!) {
+      const remaining = remainingDependencies.get(dependent)! - 1;
+      remainingDependencies.set(dependent, remaining);
+      if (remaining === 0) {
+        ready.push(dependent);
+        ready.sort();
+      }
+    }
+  }
+
+  if (order.length !== tasks.length) {
+    const cycle = findCycle(tasks);
+    throw new Error(`cycle detected: ${cycle!.join(" -> ")}`);
+  }
+
+  const layers: string[][] = [];
+  const layerById = new Map<string, number>();
+  const earliest: Record<string, { start: number; finish: number }> = {};
+  const criticalPathById = new Map<string, string[]>();
+
+  for (const id of order) {
+    const task = byId.get(id)!;
+    let layer = 0;
+    let start = 0;
+    let bestPath: string[] = [];
+
+    for (const dependency of task.dependsOn) {
+      layer = Math.max(layer, layerById.get(dependency)! + 1);
+      const dependencyFinish = earliest[dependency]!.finish;
+      const dependencyPath = criticalPathById.get(dependency)!;
+      if (dependencyFinish > start ||
+          (dependencyFinish === start && (bestPath.length === 0 || comparePaths(dependencyPath, bestPath) < 0))) {
+        start = dependencyFinish;
+        bestPath = dependencyPath;
+      }
+    }
+
+    layerById.set(id, layer);
+    (layers[layer] ??= []).push(id);
+    earliest[id] = { start, finish: start + task.duration };
+    criticalPathById.set(id, [...bestPath, id]);
+  }
+
+  let totalDuration = 0;
+  let criticalPath: string[] = [];
+  for (const id of order) {
+    const finish = earliest[id]!.finish;
+    const path = criticalPathById.get(id)!;
+    if (finish > totalDuration ||
+        (finish === totalDuration && (criticalPath.length === 0 || comparePaths(path, criticalPath) < 0))) {
+      totalDuration = finish;
+      criticalPath = path;
+    }
+  }
+
+  for (const layer of layers) layer.sort();
+  return { order, layers, earliest, totalDuration, criticalPath };
+}
+
+async function main(): Promise<void> {
+  const args = Bun.argv.slice(2);
+  if (args.length === 0) throw new Error("usage: bun run src/cli.ts plan INPUT.json");
+  if (args[0] !== "plan") throw new Error(`unknown command: ${args[0]}`);
+  if (args.length < 2) throw new Error("missing input file");
+  if (args.length > 2) throw new Error(`unknown argument or flag: ${args[2]}`);
+
+  let text: string;
+  try {
+    text = await Bun.file(args[1]!).text();
+  } catch (error) {
+    throw new Error(`cannot read ${args[1]}: ${error instanceof Error ? error.message : String(error)}`);
+  }
+
+  let input: unknown;
+  try {
+    input = JSON.parse(text);
+  } catch (error) {
+    throw new Error(`invalid JSON: ${error instanceof Error ? error.message : String(error)}`);
+  }
+
+  console.log(JSON.stringify(createPlan(validateInput(input))));
+}
+
+if (import.meta.main) {
+  main().catch((error) => {
+    console.error(`Error: ${error instanceof Error ? error.message : String(error)}`);
+    process.exitCode = 1;
+  });
+}

