+import { describe, expect, test } from "bun:test";
+import { createPlan, validateInput } from "./cli";
+
+describe("dependency planner", () => {
+  test("plans deterministically with concurrency and a critical-path tie", () => {
+    const tasks = validateInput({ tasks: [
+      { id: "deploy", duration: 1, dependsOn: ["build", "test"] },
+      { id: "test", duration: 3, dependsOn: ["lint"] },
+      { id: "build", duration: 3, dependsOn: ["lint"] },
+      { id: "lint", duration: 2 },
+      { id: "docs", duration: 0 },
+    ] });
+
+    expect(createPlan(tasks)).toEqual({
+      order: ["docs", "lint", "build", "test", "deploy"],
+      layers: [["docs", "lint"], ["build", "test"], ["deploy"]],
+      earliest: {
+        docs: { start: 0, finish: 0 },
+        lint: { start: 0, finish: 2 },
+        build: { start: 2, finish: 5 },
+        test: { start: 2, finish: 5 },
+        deploy: { start: 5, finish: 6 },
+      },
+      totalDuration: 6,
+      criticalPath: ["lint", "build", "deploy"],
+    });
+  });
+
+  test("handles an empty task list", () => {
+    expect(createPlan(validateInput({ tasks: [] }))).toEqual({
+      order: [], layers: [], earliest: {}, totalDuration: 0, criticalPath: [],
+    });
+  });
+
+  test("reports a deterministic concrete cycle", () => {
+    const tasks = validateInput({ tasks: [
+      { id: "c", duration: 1, dependsOn: ["b"] },
+      { id: "b", duration: 1, dependsOn: ["a"] },
+      { id: "a", duration: 1, dependsOn: ["c"] },
+    ] });
+    expect(() => createPlan(tasks)).toThrow("cycle detected: a -> c -> b -> a");
+  });
+
+  test.each([
+    [{}, '"tasks" must be an array'],
+    [{ tasks: [{ id: "", duration: 1 }] }, "id must be a non-empty string"],
+    [{ tasks: [{ id: "a", duration: Number.NaN }] }, "finite non-negative number"],
+    [{ tasks: [{ id: "a", duration: 1 }, { id: "a", duration: 2 }] }, "duplicate task id"],
+    [{ tasks: [{ id: "a", duration: 1, dependsOn: ["x"] }] }, "unknown task"],
